script:
# AIG: default the mandatory AIG Cost Center on Purchase Order.
# Order: first item cost_center -> creating user's first UNSCOPED Cost Center
# user permission (root CC / Head Office excluded: enterprise users cannot
# read documents carrying them) -> company default.
if not doc.get("aig_cost_center"):
    cc = None
    for item in (doc.items or []):
        if item.get("cost_center"):
            cc = item.get("cost_center")
            break
    if not cc:
        rows = frappe.get_all("User Permission",
                              filters={"user": frappe.session.user,
                                       "allow": "Cost Center"},
                              fields=["for_value", "applicable_for"])
        for r in rows:
            if r.for_value in ("Adama Investment Group - AIG",
                               "Head Office - AIG"):
                continue
            if r.applicable_for and r.applicable_for != "Cost Center":
                continue
            cc = r.for_value
            break
    if not cc:
        cc = frappe.db.get_value("Company", doc.company, "cost_center")
    if cc in ("Adama Investment Group - AIG", "Head Office - AIG"):
        cc = None
    if cc:
        doc.set("aig_cost_center", cc)
for item in (doc.items or []):
    if not item.get("cost_center") and doc.get("aig_cost_center"):
        item.cost_center = doc.get("aig_cost_center")

# AIG - default the requester and enterprise cost center on a new Stock
# Request. IMPORTANT: never stamp the root CC ('Adama Investment Group - AIG')
# or Head Office: enterprise-scoped users cannot read documents that carry
# them, which breaks the workflow buttons on their own requests. Prefer the
# warehouse's enterprise CC; fall back to the user's first unscoped Cost
# Center user permission.
if not doc.get("aig_requested_by"):
    doc.aig_requested_by = frappe.session.user
if not doc.get("aig_cost_center"):
    cc = None
    for it in (doc.items or []):
        if it.warehouse:
            cc = frappe.db.get_value("Warehouse", it.warehouse, "aig_cost_center")
            if cc:
                break
    if not cc:
        rows = frappe.get_all("User Permission",
                              filters={"user": frappe.session.user,
                                       "allow": "Cost Center"},
                              fields=["for_value", "applicable_for"])
        for r in rows:
            if r.for_value in ("Adama Investment Group - AIG", "Head Office - AIG"):
                continue
            if r.applicable_for and r.applicable_for != "Cost Center":
                continue
            cc = r.for_value
            break
    if not cc:
        cc = frappe.db.get_value("Company", doc.company, "cost_center")
    if cc in ("Adama Investment Group - AIG", "Head Office - AIG"):
        cc = None
    if cc:
        doc.aig_cost_center = cc
hdr = doc.get("aig_cost_center")
if hdr:
    for it in (doc.items or []):
        if not it.get("cost_center"):
            it.cost_center = hdr
        elif it.cost_center in ("Adama Investment Group - AIG", "Head Office - AIG"):
            it.cost_center = hdr

# AIG - capture enterprise dimensions and flag Main Store final approval.
recv_wh = doc.to_warehouse
src_wh = doc.from_warehouse
if not recv_wh:
    for it in (doc.items or []):
        if it.t_warehouse:
            recv_wh = it.t_warehouse
            break
if not src_wh:
    for it in (doc.items or []):
        if it.s_warehouse:
            src_wh = it.s_warehouse
            break

is_main = 0
dst_cc = None
src_cc = None
if recv_wh:
    dst_cc = frappe.db.get_value("Warehouse", recv_wh, "aig_cost_center")
    is_main = frappe.db.get_value("Warehouse", recv_wh, "aig_is_main_store") or 0
if src_wh:
    src_cc = frappe.db.get_value("Warehouse", src_wh, "aig_cost_center")

doc.aig_needs_main_approval = 1 if (doc.purpose == "Material Receipt" and is_main) else 0
if src_cc and not doc.get("aig_source_cost_center"):
    doc.aig_source_cost_center = src_cc
if dst_cc and not doc.get("aig_dest_cost_center"):
    doc.aig_dest_cost_center = dst_cc
if not doc.get("aig_cost_center"):
    fallback = dst_cc or src_cc
    if not fallback:
        fallback = frappe.db.get_value("User Permission",
                                       {"user": frappe.session.user, "allow": "Cost Center"},
                                       "for_value")
    if fallback:
        doc.aig_cost_center = fallback

# self-heal: fill header aig_cost_center from warehouse CC
if not doc.get("aig_cost_center"):
    doc.aig_cost_center = dst_cc or src_cc

# AIG issue control: a Material Issue must reference an APPROVED Stock Request
# (Model 19) and may not issue more than the approved remaining quantity.
if doc.purpose == "Material Issue":
    mr = doc.get("aig_material_request")
    if not mr:
        for it in (doc.items or []):
            if it.material_request:
                mr = it.material_request
                break
    if not mr:
        frappe.throw("AIG issue: link the approved Stock Request (Model 19) in "
                     "'Against Stock Request' before posting an issue.")
    mr_doc = frappe.get_doc("Material Request", mr)
    if mr_doc.workflow_state != "Approved":
        frappe.throw("AIG issue: Stock Request " + str(mr) + " is not Approved (state: "
                     + str(mr_doc.workflow_state) + ").")

    requested = {}
    for r in (mr_doc.items or []):
        requested[r.item_code] = (requested.get(r.item_code) or 0) + (r.qty or 0)

    rows = frappe.db.sql(
        "select sed.item_code as item_code, sum(sed.qty) as qty "
        "from `tabStock Entry Detail` sed "
        "join `tabStock Entry` se on se.name = sed.parent "
        "where se.aig_material_request = %s and se.docstatus = 1 "
        "group by sed.item_code", (mr,), as_dict=True)
    already = {}
    for row in (rows or []):
        already[row.item_code] = row.qty or 0

    this_issue = {}
    for it in (doc.items or []):
        this_issue[it.item_code] = (this_issue.get(it.item_code) or 0) + (it.qty or 0)

    for code in this_issue:
        allowed = requested.get(code)
        if allowed is None:
            frappe.throw("AIG issue: item " + str(code) + " is not on approved Stock Request "
                         + str(mr) + ".")
        total = (already.get(code) or 0) + this_issue[code]
        if total > allowed:
            frappe.throw("AIG issue: item " + str(code) + " would total " + str(total)
                         + " against an approved quantity of " + str(allowed)
                         + ". Reduce the issue or amend the request.")

# AIG - keep every request line on the requesting enterprise's cost center so
# accounting posts to the correct enterprise (never the Head Office default).
hdr = doc.get("aig_cost_center")
if hdr:
    for it in (doc.items or []):
        it.cost_center = hdr

# AIG - keep every stock-entry line on the enterprise cost center of the document
# so accounting posts to the correct enterprise (never the Head Office default).
hdr = doc.get("aig_cost_center")
if hdr:
    for it in (doc.items or []):
        it.cost_center = hdr

# AIG: every Journal Entry line must carry a Cost Center.
# Rows default from the header, then from the Company default; a line that
# would still post without one is blocked. (Config layer - no core edits.)
company_cc = None
if doc.company:
    company_cc = frappe.db.get_value("Company", doc.company, "cost_center")  # v16 default-CC fieldname
for row in (doc.get("accounts") or []):
    if not row.get("cost_center"):
        cc = doc.get("cost_center") or company_cc
        if cc:
            row.cost_center = cc
for row in (doc.get("accounts") or []):
    if not row.get("cost_center"):
        frappe.throw("AIG: Cost Center is required on Journal Entry row for account " + str(row.get("account")))

# AIG: Payment Entry must carry a Cost Center (flows to all its GL rows).
if not doc.get("cost_center"):
    cc = frappe.db.get_value("Company", doc.company, "cost_center")  # v16 default-CC fieldname
    if cc:
        doc.cost_center = cc
if not doc.get("cost_center"):
    frappe.throw("AIG: Cost Center is required on Payment Entry for enterprise-level Balance Sheet tracking.")

# AIG: Sales/Purchase Invoice must carry a Cost Center on header and items.
if not doc.get("cost_center"):
    cc = frappe.db.get_value("Company", doc.company, "cost_center")  # v16 default-CC fieldname
    if cc:
        doc.cost_center = cc
for row in (doc.get("items") or []):
    if not row.get("cost_center") and doc.get("cost_center"):
        row.cost_center = doc.get("cost_center")
for row in (doc.get("taxes") or []):
    if not row.get("cost_center") and doc.get("cost_center"):
        row.cost_center = doc.get("cost_center")
missing = []
for row in (doc.get("items") or []):
    if not row.get("cost_center"):
        missing.append(str(row.get("item_code") or row.idx))
if missing:
    frappe.throw("AIG: Cost Center is required on Sales Invoice item rows: " + ", ".join(missing))
if not doc.get("cost_center"):
    frappe.throw("AIG: Cost Center is required on Sales Invoice for enterprise-level Balance Sheet tracking.")

# AIG: Sales/Purchase Invoice must carry a Cost Center on header and items.
if not doc.get("cost_center"):
    cc = frappe.db.get_value("Company", doc.company, "cost_center")  # v16 default-CC fieldname
    if cc:
        doc.cost_center = cc
for row in (doc.get("items") or []):
    if not row.get("cost_center") and doc.get("cost_center"):
        row.cost_center = doc.get("cost_center")
for row in (doc.get("taxes") or []):
    if not row.get("cost_center") and doc.get("cost_center"):
        row.cost_center = doc.get("cost_center")
missing = []
for row in (doc.get("items") or []):
    if not row.get("cost_center"):
        missing.append(str(row.get("item_code") or row.idx))
if missing:
    frappe.throw("AIG: Cost Center is required on Purchase Invoice item rows: " + ", ".join(missing))
if not doc.get("cost_center"):
    frappe.throw("AIG: Cost Center is required on Purchase Invoice for enterprise-level Balance Sheet tracking.")

# AIG migration staging validation - runs before the batch is saved.
rows = doc.rows or []
doc.total_rows = len(rows)
valid = 0
warn = 0
err = 0
dup = 0

# frequency maps for within-batch duplicate detection (never auto-merge)
name_freq = {}
code_freq = {}
for r in rows:
    nm = (r.raw_item_name or "").strip().lower()
    cd = (r.item_code or "").strip()
    if nm:
        name_freq[nm] = name_freq.get(nm, 0) + 1
    if cd:
        code_freq[cd] = code_freq.get(cd, 0) + 1

EXCEL_EPOCH = frappe.utils.getdate("1899-12-30")

for r in rows:
    msgs = []
    status = "Valid"

    # ---- date: Excel serial vs real date vs invalid/ambiguous
    raw = (r.raw_date or "").strip()
    r.date_is_excel_serial = 0
    if raw:
        serial = None
        try:
            num = float(raw)
            if num == int(num) and 1 <= num <= 60000:
                serial = int(num)
        except Exception:
            serial = None
        if serial:
            r.date_is_excel_serial = 1
            conv = frappe.utils.add_days(EXCEL_EPOCH, serial)
            r.date_converted = conv
            if not r.posting_date:
                r.posting_date = conv
        else:
            try:
                conv = frappe.utils.getdate(raw)
                r.date_converted = conv
                if not r.posting_date:
                    r.posting_date = conv
            except Exception:
                msgs.append("Raw date '" + raw + "' is not a valid date or Excel serial - review.")
                status = "Error"

    # ---- quantity
    qraw = (r.raw_qty or "").strip()
    if qraw:
        try:
            q = float(qraw.replace(",", ""))
            if q < 0:
                msgs.append("Negative source quantity - review (not auto-corrected).")
                if status == "Valid":
                    status = "Warning"
        except Exception:
            msgs.append("Source quantity '" + qraw + "' is not numeric - review.")
            status = "Error"

    # ---- opening balance requires full mapping + valuation
    if r.record_type == "Opening Balance":
        if not r.item_code:
            msgs.append("Opening balance needs a mapped Item.")
            status = "Error"
        if not r.warehouse:
            msgs.append("Opening balance needs a mapped Warehouse.")
            status = "Error"
        if not r.uom:
            msgs.append("Opening balance needs a mapped UOM.")
            status = "Error"
        if not r.qty:
            msgs.append("Opening balance needs a mapped Quantity.")
            status = "Error"
        if not r.valuation_rate:
            msgs.append("Opening balance missing valuation data - review (do not guess).")
            if status == "Valid":
                status = "Warning"

    # ---- classification guards
    if r.record_type in ["Property / Fixed Asset", "Form / Voucher", "Biological Asset"]:
        msgs.append("Non-consumable classification - confirm handling with Finance/Property.")
        if status == "Valid":
            status = "Warning"
    if r.record_type in ["", "Unknown"]:
        msgs.append("Record type not classified - map before import.")
        if status == "Valid":
            status = "Warning"

    # ---- store mapping
    if (r.raw_store or "").strip() and not r.warehouse:
        msgs.append("Source store '" + (r.raw_store or "") + "' is not mapped to a Warehouse.")
        if status == "Valid":
            status = "Warning"

    # ---- duplicate candidate (flag only)
    isdup = 0
    nm = (r.raw_item_name or "").strip().lower()
    cd = (r.item_code or "").strip()
    if cd and code_freq.get(cd, 0) > 1:
        isdup = 1
    elif nm and name_freq.get(nm, 0) > 1:
        isdup = 1
    r.is_duplicate_candidate = isdup
    if isdup:
        msgs.append("Possible duplicate within the batch - review, do not auto-merge.")
        if status == "Valid":
            status = "Warning"

    r.validation_status = status
    r.validation_messages = "\n".join(msgs)
    if status == "Valid":
        valid += 1
    elif status == "Warning":
        warn += 1
    else:
        err += 1
    if isdup:
        dup += 1

doc.valid_rows = valid
doc.warning_rows = warn
doc.error_rows = err
doc.duplicate_rows = dup
if len(rows) and not err and doc.status in ["Draft", "Staged"]:
    doc.status = "Validated"

# AIG - a stock request (Material Issue / Model 19) may only contain STOCK
# items; non-stock items belong to Purchase-type requests (Procurement).
if doc.material_request_type == "Material Issue":
    bad = []
    for it in (doc.items or []):
        if not it.item_code:
            continue
        is_stock = frappe.db.get_value("Item", it.item_code, "is_stock_item")
        if not is_stock:
            bad.append(it.item_code)
    if bad:
        frappe.throw(
            "AIG stock request: these items are NOT stock items and cannot be "
            "issued from a store: " + str(bad) + ". Use a stock item (for demo: "
            "AIG-INV-FEED 'AIG Demo Dairy Feed' -- 500 bags in Dairy Farm Store), "
            "or raise a Purchase-type request via a Procurement Officer."
        )

# AIG - SE CC Normalize (Before Validate): ERPNext injects the Company
# default Cost Center (Head Office - AIG) into new Stock Entry rows/header.
# Normalize everything to the document enterprise CC (header, else the
# destination/source warehouse CC) BEFORE validation and GL posting: empty
# rows get filled, injected Head Office values are overwritten silently, and
# a genuinely foreign enterprise CC (no header dimension derivable) throws.
row_src = None
row_dst = None
src_cc = None
if doc.from_warehouse:
    src_cc = frappe.db.get_value("Warehouse", doc.from_warehouse, "aig_cost_center")
for it in (doc.items or []):
    if it.s_warehouse and not row_src:
        row_src = frappe.db.get_value("Warehouse", it.s_warehouse, "aig_cost_center")
    if it.t_warehouse and not row_dst:
        row_dst = frappe.db.get_value("Warehouse", it.t_warehouse, "aig_cost_center")
hdr = doc.get("aig_cost_center") or row_dst or row_src or src_cc
if hdr:
    doc.aig_cost_center = hdr
foreign = []
for it in (doc.items or []):
    if hdr:
        it.cost_center = hdr
    elif it.cost_center == "Head Office - AIG":
        it.cost_center = None
    elif it.cost_center:
        foreign.append(it.cost_center)
if foreign:
    frappe.throw("Row cost center(s) " + ", ".join(foreign) + " do not belong "
                 "to any enterprise cost center on this document. Pick the "
                 "correct enterprise cost center.")

# AIG - MR CC Normalize (Before Validate): the workflow read check on the
# saved doc fails if the header carries a CC outside the requester's scope
# (root CC / Head Office). Derive the enterprise CC from the row warehouse,
# overwrite any root/HO value, and sync row cost centers. Runs before the
# workflow state is committed, so apply_workflow's doc-read always sees a
# document within the owner's enterprise scope. HARDENED (157b): if the
# header must be derived but NO row warehouse carries an aig_cost_center,
# throw naming the warehouses - a silent pass-through here used to leave the
# request with root/HO costing, which strips every workflow action button
# with no error. No getattr / flt / str.format (sandbox).
row_cc = None
missing = ""
for it in (doc.items or []):
    if it.warehouse:
        row_cc = frappe.db.get_value("Warehouse", it.warehouse, "aig_cost_center")
        if row_cc:
            break
        if missing:
            missing = missing + ", " + it.warehouse
        else:
            missing = it.warehouse
    else:
        if missing:
            missing = missing + ", (no warehouse)"
        else:
            missing = "(no warehouse)"
hdr = doc.get("aig_cost_center")
if hdr in ("Adama Investment Group - AIG", "Head Office - AIG", None, ""):
    if not row_cc:
        frappe.throw("AIG Cost Center: no cost center could be derived for "
                     "this request - warehouse(s) " + missing +
                     " have no AIG Cost Center configured (set it on the "
                     "Warehouse record) and the request header carries the "
                     "root/Head-Office cost center. Left unfixed, this "
                     "request would show no approval buttons at all.")
    hdr = row_cc
if hdr:
    doc.aig_cost_center = hdr
    for it in (doc.items or []):
        if it.cost_center in ("Adama Investment Group - AIG",
                              "Head Office - AIG", None, ""):
            it.cost_center = hdr
